blocks.check:
const bg = (i) => getComputedStyle(document.querySelectorAll('.badge')[i]).backgroundColor;
const css = document.querySelector('#mine').textContent;
assert(/\[data-state/.test(css), 'Use attribute selectors such as [data-state="up"].');
assert(bg(0) === 'rgb(26, 127, 55)', `The up badge is ${bg(0)}; expected rgb(26, 127, 55).`);
assert(bg(1) === 'rgb(154, 103, 0)', `The degraded badge is ${bg(1)}; expected rgb(154, 103, 0).`);
assert(bg(2) === 'rgb(176, 0, 32)', `The down badge is ${bg(2)}; expected rgb(176, 0, 32).`);
assert(bg(3) === 'rgb(110, 119, 129)', 'The badge without data-state should keep the grey background.');
assert(document.querySelectorAll('.badge[class~="up"], .badge[class~="down"]').length === 0, 'Do not add classes.');

const [go, cancel] = document.querySelectorAll('#toolbar button');
const css = document.querySelector('#mine').textContent;
assert(!/!\s*important/i.test(css), 'No !important allowed.');
assert(!go.hasAttribute('style'), 'No inline style on the button.');
assert(document.querySelector('#theme').textContent.includes('rgb(120, 120, 120)'), 'Do not edit the theme stylesheet.');
assert(getComputedStyle(go).backgroundColor === 'rgb(10, 127, 156)', `Deploy is still ${getComputedStyle(go).backgroundColor}. Compare your selector's specificity with (1,0,1).`);
assert(getComputedStyle(cancel).backgroundColor === 'rgb(120, 120, 120)', 'Cancel must stay grey: your rule matches too much.');

const css = document.querySelector('#mine').textContent;
assert(/@media/.test(css), 'Use a @media rule.');
const tracks = (v) => { const s = v.trim().replace(/\([^)]*\)/g, (p) => p.replace(/\s+/g, '')); const m = /^repeat\((\d+),/.exec(s); return m ? Number(m[1]) : s.split(/\s+/).length; };
const specified = [];
for (const r of document.querySelector('#mine').sheet.cssRules) {
  const inner = r instanceof CSSMediaRule ? [...r.cssRules] : [r];
  for (const x of inner) if (x.style && x.style.gridTemplateColumns) specified.push(tracks(x.style.gridTemplateColumns));
}
assert(specified.includes(3) && specified.includes(1), 'Declare both layouts: one rule with three columns and one with a single column.');
const cols = getComputedStyle(document.querySelector('.dash')).gridTemplateColumns.split(' ').length;
const want = innerWidth < 600 ? 1 : 3;
assert(cols === want, `This frame is ${innerWidth}px wide, so the grid should have ${want} column(s); it has ${cols}.`);

