const root = document.documentElement;
const read = () => [getComputedStyle(document.body).backgroundColor, getComputedStyle(document.body).color, getComputedStyle(document.querySelector('.card')).backgroundColor, getComputedStyle(document.querySelector('.card')).borderTopColor].join(' | ');
